var i=[{title:`Vorbereiten und bewegen`,text:`Stelle dich mit bequemem Fußabstand und Fußwinkel hin. Spanne deinen Rumpf an, lass Hüften und Knie gemeinsam beugen und halte den Druck auf den Füßen ausgeglichen. Senke dich kontrolliert bis in eine Tiefe ab, in der deine Technik stabil bleibt, und drücke dich dann durch den Boden zum Stehen hoch. Dein Oberkörperwinkel und wie weit die Knie nach vorn wandern, unterscheiden sich je nach Gliedmaßenlänge und Art der Kniebeuge.`},{title:`Tiefe und Kniebewegung`,text:`Es gibt keine Regel, dass die Knie hinter den Zehen bleiben müssen. Bei vielen Kniebeugen bewegen sie sich nach vorn, und das ist normal. Eine tiefere Kniebeuge kann nützlich sein, wenn du sie bequem und kontrolliert erreichst, doch Tiefe durch schmerzende Gelenke oder verlorenes Gleichgewicht zu erzwingen, hilft nicht. Die Fersen zu erhöhen oder die Standbreite zu ändern, verändert die Bewegung, und keines von beiden macht eine Kniebeuge automatisch besser.`},{title:`Häufige Fehler und Korrekturen`,text:`Abhebende Fersen, unkontrolliert nach innen fallende Knie und ein verlorener stabiler Rumpf deuten oft darauf hin, dass Tiefe, Gleichgewicht oder Last nicht zu dem passen, was du schon kontrollieren kannst. Versuche ein leichteres Gewicht, eine Pause kurz über dem schweren Punkt oder einen Stuhl als Ziel. Deine Knie können ungefähr in dieselbe Richtung zeigen wie deine Zehen, ohne einem starren Weg zu folgen.`},{title:`Beispiel für die Steigerung`,text:`Beginne mit Aufstehen vom Stuhl oder Kniebeugen mit Körpergewicht. Ergänze eine Goblet-Kniebeuge, sobald das Muster zuverlässig ist, dann Kurzhanteln oder eine Langhantel, wenn du möchtest. Mache zum Beispiel zwei Sätze mit 8 kontrollierten Wiederholungen, bevor du Last hinzufügst. Fortgeschrittenere Variationen sind optional, und du brauchst sie nicht, um fit zu werden.`},{title:`TrainUp nutzen`,text:`Dein Plan wählt Kniebeugen mit Körpergewicht, Goblet-Kniebeugen oder Kniebeugen mit Last, die zu deiner Ausrüstung, deinem Level, deiner Koordination und allen Einschränkungen passen, die du im Profil angibst, etwa beim Knie. Behalte beim Steigern dieselbe Tiefe und Technik bei, damit höhere Zahlen echten Fortschritt zeigen.`}];var t=[{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: Technik beim Krafttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};